/*
 * SAT Climb question bank: Reading and Writing.
 *
 * Every question here is ORIGINAL, written for this site in the style of the digital SAT.
 * Do not paste in questions from College Board, Bluebook, Khan Academy, or commercial prep
 * books -- they are copyrighted. Use them as models and write new ones instead.
 *
 * Status: first draft, not yet human-reviewed. Run `node tools/check-questions.js`
 * after editing.
 *
 * Fields (short names keep the file readable at volume):
 *   s  skill id (see SKILLS)          d  difficulty: 1 easy, 2 medium, 3 hard
 *   p  passage; blank lines separate paragraphs, lines starting with "•" become a list,
 *      a paragraph that is exactly "Text 1" / "Text 2" becomes a label, "______" a blank
 *   t  optional table {title, headers, rows}
 *   q  optional question stem (defaults to STEMS[s])
 *   c  four answer choices            a  correct letter            e  explanation
 *
 * IDs are assigned by position within each skill (wic-001, wic-002, ...) and progress is
 * saved against them, so ALWAYS APPEND new questions; never reorder or delete old ones.
 */
(function () {
  const SKILLS = [
    { id: 'wic', name: 'Words in Context', domain: 'Craft and Structure' },
    { id: 'tsp', name: 'Text Structure and Purpose', domain: 'Craft and Structure' },
    { id: 'ctc', name: 'Cross-Text Connections', domain: 'Craft and Structure' },
    { id: 'cid', name: 'Central Ideas and Details', domain: 'Information and Ideas' },
    { id: 'coe', name: 'Command of Evidence', domain: 'Information and Ideas' },
    { id: 'inf', name: 'Inferences', domain: 'Information and Ideas' },
    { id: 'bnd', name: 'Boundaries', domain: 'Standard English Conventions' },
    { id: 'fss', name: 'Form, Structure, and Sense', domain: 'Standard English Conventions' },
    { id: 'trn', name: 'Transitions', domain: 'Expression of Ideas' },
    { id: 'rsy', name: 'Rhetorical Synthesis', domain: 'Expression of Ideas' },
  ];

  const SEC = 'Which choice completes the text so that it conforms to the conventions of Standard English?';
  const STEMS = {
    wic: 'Which choice completes the text with the most logical and precise word or phrase?',
    tsp: 'Which choice best describes the main purpose of the text?',
    ctc: 'Based on the texts, how would the author of Text 2 most likely respond to Text 1?',
    cid: 'Which choice best states the main idea of the text?',
    coe: 'Which choice most effectively uses data from the table to complete the statement?',
    inf: 'Which choice most logically completes the text?',
    bnd: SEC,
    fss: SEC,
    trn: 'Which choice completes the text with the most logical transition?',
    rsy: 'Which choice most effectively uses relevant information from the notes to accomplish this goal?',
  };
  const NOTES = 'While researching a topic, a student has taken the following notes:';

  const RAW = [
    // ---------------------------------------------------------------- Words in Context
    { s: 'wic', d: 1, p: `Marine biologist Ayana Brooks was initially ______ about the new tagging method, but after seeing the device track sea turtles reliably for six months, she became one of its strongest advocates.`,
      c: ['skeptical', 'enthusiastic', 'generous', 'famous'], a: 'A',
      e: `"Initially ... but ... became one of its strongest advocates" signals a change from doubt to support, so the blank needs a word meaning doubtful: "skeptical." "Enthusiastic" describes where she ended up, not where she started.` },
    { s: 'wic', d: 1, p: `The town library is so ______ that residents joke it has more volunteers than books: on any given afternoon, dozens of people are shelving, reading aloud, or leading workshops.`,
      c: ['quiet', 'lively', 'expensive', 'ancient'], a: 'B',
      e: `The colon introduces support for the blank: dozens of people shelving, reading aloud, and leading workshops describe a busy, energetic place, so "lively" fits. Nothing in the text supports "quiet," "expensive," or "ancient."` },
    { s: 'wic', d: 1, p: `Because the bridge's original blueprints had been lost, engineers had to ______ its design by measuring every beam and cable by hand before they could plan repairs.`,
      c: ['celebrate', 'reconstruct', 'ignore', 'postpone'], a: 'B',
      e: `With the blueprints lost, the engineers measured the bridge to rebuild their understanding of its design, which is what "reconstruct" means here. They could not "ignore" the design and still plan repairs.` },
    { s: 'wic', d: 2, p: `Although critics praised the composer's early symphonies, her later chamber works were largely ______ during her lifetime; only decades after her death did musicians begin to perform and record them widely.`,
      c: ['imitated', 'commissioned', 'revised', 'overlooked'], a: 'D',
      e: `"Although critics praised" the early work sets up a contrast, and the second clause says the later works were performed widely only after her death. So during her life they were ignored: "overlooked."` },
    { s: 'wic', d: 2, p: `Researchers studying honeybee colonies found that worker bees do not perform a single task for life; instead, their roles are remarkably ______, shifting from nursing larvae to guarding the hive to foraging as the colony's needs change.`,
      c: ['rigid', 'ancient', 'flexible', 'solitary'], a: 'C',
      e: `"Instead" contrasts with "a single task for life," and the roles are described as "shifting ... as the colony's needs change." That describes roles that adapt: "flexible." "Rigid" is the opposite of what the text describes.` },
    { s: 'wic', d: 2, p: `The novelist's prose is notably ______: she rarely uses two words where one will do, and many of her chapters are shorter than a single page.`,
      c: ['economical', 'ornate', 'hesitant', 'archaic'], a: 'A',
      e: `The colon explains the blank: she avoids extra words and writes very short chapters. Prose that uses no more words than necessary is "economical." "Ornate" (heavily decorated) means the opposite.` },
    { s: 'wic', d: 2, p: `Early accounts of the expedition, written by its leader, ______ the contributions of the local guides, mentioning them only in passing; later historians, drawing on the guides' own testimony, showed that the guides had chosen nearly every route.`,
      c: ['exaggerated', 'minimized', 'documented', 'questioned'], a: 'B',
      e: `The leader mentioned the guides "only in passing," even though they chose nearly every route. Treating something important as small is "minimized." "Exaggerated" is the reverse.` },
    { s: 'wic', d: 3, p: `Geologist Hiroshi Tanaka cautions that the newly discovered rock layer should not be treated as a ______ record of ancient climate: erosion removed sections of it at several points, so some intervals are missing entirely.`,
      c: ['comprehensive', 'dubious', 'recent', 'partial'], a: 'A',
      e: `Tanaka warns against treating the layer as something it is not, and the reason given is that intervals are missing. So it should not be treated as a complete record: "comprehensive." "Partial" describes what the record actually is, so it contradicts "should not."` },
    { s: 'wic', d: 3, p: `Some economists argue that the policy's benefits have been ______: although unemployment fell in the year after it was enacted, similar declines occurred in neighboring regions that adopted no such policy.`,
      c: ['unprecedented', 'immediate', 'overstated', 'permanent'], a: 'C',
      e: `Neighboring regions saw the same drop without the policy, which suggests the policy may not deserve credit for it. Claiming more credit than the evidence supports means the benefits were "overstated."` },
    { s: 'wic', d: 3, p: `In her study of medieval trade networks, historian Leila Haddad resists the temptation to ______ the merchants she studies; she documents their ingenuity and courage but also describes in detail the exploitative labor practices on which much of their wealth depended.`,
      c: ['romanticize', 'condemn', 'misidentify', 'overlook'], a: 'A',
      e: `Haddad praises the merchants' ingenuity but refuses to hide the exploitation behind their wealth. The temptation she resists is presenting them in an idealized, purely positive light: "romanticize." She does describe their faults, so "condemn" is not something she avoids entirely.` },

    // ---------------------------------------------------------------- Text Structure and Purpose
    { s: 'tsp', d: 1, p: `Many people think of deserts as lifeless, but the Sonoran Desert is home to more than 2,000 species of plants. Some, like the saguaro cactus, store water in their thick stems. Others, like many wildflowers, survive dry periods as seeds and bloom only after heavy rains.`,
      c: ['To argue that the Sonoran Desert should be protected', 'To challenge a common belief by describing the variety of plant life in a desert', 'To explain how scientists count plant species', 'To compare the saguaro cactus with desert wildflowers in detail'], a: 'B',
      e: `The text opens with a common belief ("deserts as lifeless") and then counters it with examples of desert plants. It never argues for protection or explains counting methods, and the comparison in D is only a supporting detail.` },
    { s: 'tsp', d: 1, q: 'Which choice best describes the overall structure of the text?',
      p: `When the city of Curitiba, Brazil, needed better public transportation in the 1970s, it could not afford a subway. Instead, planners created dedicated lanes for buses; later, they added raised, tube-shaped stations where passengers paid before boarding. The system moved riders nearly as quickly as a subway at a fraction of the cost, and cities around the world went on to copy it.`,
      c: ['It presents a problem, describes a solution, and notes the solution\'s influence.', 'It describes a historical event and then argues that the event has been misunderstood.', 'It compares two cities and explains why one was more successful.', 'It lists criticisms of a plan and then responds to each one.'], a: 'A',
      e: `Problem: Curitiba needed transit but could not afford a subway. Solution: bus lanes and tube stations. Influence: other cities copied it. No misunderstanding, second city, or list of criticisms appears.` },
    { s: 'tsp', d: 1, q: 'Which choice best describes the function of the third sentence in the overall structure of the text?',
      p: `Mira had practiced the speech forty times in front of her bedroom mirror. She knew exactly where to pause and when to look up at the audience. Yet when she stepped onto the stage and saw the rows of faces, every word seemed to drain out of her head at once.`,
      c: ['It introduces a contrast with Mira\'s careful preparation described in the earlier sentences.', 'It explains why Mira chose to practice in front of a mirror.', 'It describes the audience\'s reaction to Mira\'s speech.', 'It suggests that Mira\'s speech was too long.'], a: 'A',
      e: `The first two sentences show how well prepared Mira was. "Yet" signals that the third sentence contrasts with that: despite practicing, she forgets everything. The audience never reacts, and the speech's length is never mentioned.` },
    { s: 'tsp', d: 2, p: `Biologists long assumed that plants respond to physical touch only over weeks, as when vines slowly coil around a support. But research on the Venus flytrap shows that some plants react within a fraction of a second. When an insect brushes two of the trigger hairs inside the trap within about twenty seconds, electrical signals cause the trap to snap shut.`,
      c: ['To describe how Venus flytraps attract insects', 'To present a finding that complicates an earlier assumption about plants', 'To argue that vines are less sensitive than Venus flytraps', 'To explain why scientists have difficulty studying plant behavior'], a: 'B',
      e: `The text states an old assumption (plants respond to touch slowly) and then, with "But," presents flytrap research showing a fast response. That complicates the assumption. The text explains how the trap closes, not how it attracts insects.` },
    { s: 'tsp', d: 2, q: 'Which choice best describes the function of the second sentence in the overall structure of the text?',
      p: `Historians often credit the printing press with spreading literacy across fifteenth-century Europe. Yet historian Ana Ruiz notes that books remained expensive for decades after the press's invention, and most early printed works were in Latin, a language few ordinary people could read. Literacy rates, she argues, rose significantly only when cheap pamphlets in local languages became common in the following century.`,
      c: ['It provides an example that supports the claim in the first sentence.', 'It summarizes the conclusion stated in the final sentence.', 'It presents details that cast doubt on the view described in the first sentence.', 'It explains why the printing press was invented.'], a: 'C',
      e: `The first sentence gives a common view (the press spread literacy). "Yet" introduces Ruiz's details (books were expensive and in Latin) that weaken that view. The sentence sets up the final conclusion rather than summarizing it.` },
    { s: 'tsp', d: 2, q: 'Which choice best describes the overall structure of the text?',
      p: `Many people picture glaciers as frozen, unmoving masses. In fact, glaciers flow. Under their own enormous weight, the ice deforms and slides over the ground beneath it, and some glaciers in Greenland move more than 20 meters a day. This movement shapes landscapes, carving valleys and carrying boulders hundreds of kilometers.`,
      c: ['It presents a hypothesis and describes an experiment that tested it.', 'It describes a scientific debate and explains how it was resolved.', 'It compares glaciers in Greenland with glaciers elsewhere.', 'It describes a misconception, corrects it, and then explains a consequence of the corrected view.'], a: 'D',
      e: `Misconception: glaciers are unmoving. Correction: "In fact, glaciers flow." Consequence: the movement carves valleys and moves boulders. There is no experiment, no debate, and no comparison with other glaciers.` },
    { s: 'tsp', d: 2, p: `The orchard had belonged to the Okafor family for three generations. Each autumn, Grandfather walked its rows before dawn, pressing his thumb against the fruit to judge its ripeness. This year, for the first time, he handed the basket to Chidi and stayed on the porch, watching.`,
      c: ['To describe the process of harvesting fruit in detail', 'To show a moment in which responsibility passes from one generation to another', 'To explain why Grandfather no longer enjoys working in the orchard', 'To contrast the orchard\'s past with its uncertain future'], a: 'B',
      e: `The text builds up Grandfather's long-standing ritual, then shows him handing the basket to Chidi "for the first time." That is a handoff between generations. Nothing says he no longer enjoys the work or that the future is uncertain.` },
    { s: 'tsp', d: 3, q: 'Which choice best describes the overall structure of the text?',
      p: `Some astronomers have proposed that a ninth planet, roughly five times the mass of Earth, orbits far beyond Neptune. Their evidence is indirect: several small, distant objects have unusual orbits that cluster together in a way the gravity of an unseen planet could explain. Critics counter that the clustering may be an artifact of where telescopes have happened to look, since surveys have covered only limited regions of the sky.`,
      c: ['It describes a discovery and then explains why the discovery was unexpected.', 'It presents two competing hypotheses and argues that one is better supported.', 'It introduces a hypothesis, describes the evidence for it, and then presents an objection to that evidence.', 'It describes a problem with telescopes and proposes a solution.'], a: 'C',
      e: `Sentence 1 gives the hypothesis (a ninth planet), sentence 2 gives its evidence (clustered orbits), and sentence 3 gives critics' objection to that evidence. Nothing has been discovered yet, and the text takes no side, so B is wrong too.` },
    { s: 'tsp', d: 3, q: 'Which choice best describes the function of the final sentence in the overall structure of the text?',
      p: `Linguist Maya Okonjo studies "whistled languages," in which speakers convey words by whistling the pitch and rhythm of speech. Such languages, found in mountainous regions from Turkey to Mexico, carry over distances of several kilometers, far farther than shouting. Okonjo points out that whistled languages are not separate languages at all but rather a way of transmitting an existing spoken language, much as writing transmits speech visually.`,
      c: ['It explains why whistled languages carry over long distances.', 'It challenges the claim that whistled languages exist in many regions.', 'It describes a limitation of Okonjo\'s research methods.', 'It clarifies the relationship between whistled languages and spoken languages.'], a: 'D',
      e: `The final sentence explains that a whistled language is a way of transmitting a spoken language, not a separate language, and compares it to writing. That clarifies how the two relate. The distance point comes earlier, and nothing questions where the languages are found.` },
    { s: 'tsp', d: 3, p: `Traditional economic models assume that people make decisions by carefully weighing costs and benefits. Behavioral economists have documented many exceptions: people often prefer avoiding a loss to acquiring an equivalent gain, for example. Yet economist Tomas Lindqvist argues that these findings should refine rather than replace traditional models, since the models still predict overall market behavior reasonably well.`,
      c: ['To describe a researcher\'s position on how new findings relate to an established approach', 'To argue that traditional economic models should be abandoned', 'To explain in detail why people prefer avoiding losses to acquiring gains', 'To criticize behavioral economists for ignoring market behavior'], a: 'A',
      e: `The text builds toward Lindqvist's view: behavioral findings should refine, not replace, traditional models. That is a position on how new findings relate to an established approach. B is the view Lindqvist rejects, and no one is criticized.` },

    // ---------------------------------------------------------------- Cross-Text Connections
    { s: 'ctc', d: 1, q: 'Based on the texts, how would Cole (Text 2) most likely respond to the teachers\' belief described in Text 1?',
      p: `Text 1\n\nMany teachers assign homework every night, believing that regular practice helps students remember what they learned in class. Without it, they argue, lessons fade quickly.\n\nText 2\n\nA review of dozens of studies by education researcher Dana Cole found that for elementary students, the amount of homework had little connection to test performance. For high school students, moderate homework was linked to better results, but very large amounts were not.`,
      c: ['By agreeing that nightly homework benefits students of all ages equally', 'By suggesting that the benefits of homework depend on students\' age and the amount assigned', 'By arguing that homework harms students\' ability to remember lessons', 'By claiming that teachers should assign more homework to elementary students'], a: 'B',
      e: `Cole found little benefit for elementary students and a benefit for high schoolers only at moderate amounts. That means the teachers' belief holds only in some cases, depending on age and amount. Cole never says homework is harmful.` },
    { s: 'ctc', d: 1, q: 'Based on the texts, how would Ortega (Text 2) most likely respond to the claim in Text 1 about the amount of food urban gardens produce?',
      p: `Text 1\n\nUrban gardens are often praised for supplying fresh vegetables to city residents. But the small plots typical of city gardens produce only a tiny fraction of the food a neighborhood eats.\n\nText 2\n\nSupporters of urban gardens rarely claim that the gardens can feed a city. Their real value, community organizer Luis Ortega says, lies elsewhere: gardens bring neighbors together, teach children where food comes from, and turn vacant lots into green space.`,
      c: ['He would agree that urban gardens are not worth their cost.', 'He would dispute the claim by citing data on garden harvests.', 'He would accept the claim but argue that it overlooks the gardens\' other benefits.', 'He would argue that gardens should be made larger to produce more food.'], a: 'C',
      e: `Ortega does not argue about food production; he says the gardens' "real value ... lies elsewhere." So he would accept that they produce little food but say that misses their social and educational benefits. He clearly thinks they are worthwhile, so A is wrong.` },
    { s: 'ctc', d: 1, q: 'Based on the texts, how would the researchers in Text 2 most likely describe the traditional view in Text 1?',
      p: `Text 1\n\nPaleontologists have traditionally pictured Tyrannosaurus rex as covered entirely in scaly skin, like a modern lizard.\n\nText 2\n\nFossils of several smaller relatives of T. rex show clear impressions of feathers. Because these relatives are closely related to T. rex, some researchers have suggested that T. rex itself may have had at least some feathers. However, the patches of fossilized T. rex skin found so far show scales.`,
      c: ['As possibly incomplete, given evidence of feathers in related species', 'As definitely disproven by fossil evidence', 'As based on fossils that were incorrectly dated', 'As the only view consistent with the available evidence'], a: 'A',
      e: `The researchers say T. rex "may have had at least some feathers," a cautious suggestion. Text 2 also admits that known T. rex skin shows scales, so "definitely disproven" is too strong. "Possibly incomplete" fits the hedged language.` },
    { s: 'ctc', d: 2, q: 'Based on the texts, how would Haddad (Text 2) most likely respond to the evidence Patel cites in Text 1?',
      p: `Text 1\n\nSocial media is often blamed for shortening people's attention spans. Psychologist Rina Patel points to surveys in which adults report finding it harder to concentrate on long books than they did a decade ago.\n\nText 2\n\nSelf-reported difficulty concentrating is not the same as a measured decline in attention. In laboratory tests of sustained attention, researcher Omar Haddad found no significant difference between heavy and light social media users. People may simply be choosing to spend their attention differently.`,
      c: ['He would argue that the surveys show attention spans have actually increased.', 'He would question whether survey responses accurately reflect people\'s actual ability to pay attention.', 'He would agree that the surveys demonstrate a decline caused by social media.', 'He would claim that adults read more long books than they did a decade ago.'], a: 'B',
      e: `Patel's evidence is self-reported surveys. Text 2 opens by saying that self-reported difficulty "is not the same as a measured decline," which questions what surveys can show. Haddad never says attention increased.` },
    { s: 'ctc', d: 2, q: 'Based on the texts, how would the transportation researchers in Text 2 most likely respond to the planners\' reasoning in Text 1?',
      p: `Text 1\n\nSome city planners argue that widening highways is the best way to reduce traffic congestion: more lanes means more room for cars, and therefore shorter commutes.\n\nText 2\n\nTransportation researchers have repeatedly observed a phenomenon called induced demand. When a highway is widened, driving becomes more convenient, so more people choose to drive, and within a few years congestion often returns to its previous level.`,
      c: ['By claiming that congestion is caused mainly by road construction', 'By agreeing that wider highways permanently shorten commutes', 'By suggesting that highways should be widened more quickly', 'By arguing that the planners have overlooked how added lanes change people\'s behavior'], a: 'D',
      e: `The planners assume the number of drivers stays the same. Induced demand means wider roads attract more drivers, so the researchers would say the planners ignored that change in behavior. B is the opposite of their finding.` },
    { s: 'ctc', d: 2, q: 'Based on the texts, how would Park (Text 2) most likely respond to the usual reading described in Text 1?',
      p: `Text 1\n\nThe novels of the nineteenth-century writer Elena Varga are usually read as straightforward romances. Their plots center on courtship, and nearly all of them end in marriage.\n\nText 2\n\nLiterary scholar June Park argues that Varga's novels are sharper than their plots suggest. The marriages that close the books are often described in a few flat sentences, while the heroines' earlier independence is depicted in vivid detail. Park sees this imbalance as a quiet critique of the limited options available to women of Varga's era.`,
      c: ['She would agree that the novels are primarily celebrations of marriage.', 'She would claim that Varga did not intend her novels to be published.', 'She would argue that the usual reading overlooks how the novels\' style complicates their endings.', 'She would argue that the plots of the novels do not center on courtship.'], a: 'C',
      e: `Park accepts the plots as described but points to how they are written (flat endings, vivid independence) as a hidden critique. So the usual reading misses what the style does to the endings. She does not deny the plots center on courtship (D).` },
    { s: 'ctc', d: 2, q: 'Based on the texts, how would the author of Text 2 most likely characterize the initial findings described in Text 1?',
      p: `Text 1\n\nEarly studies of "power posing" (standing in an expansive posture before a stressful event) reported that the practice raised people's confidence and changed their hormone levels.\n\nText 2\n\nLater, larger studies that attempted to replicate the power-posing research did not find the reported hormone changes. Some did find that people felt somewhat more confident after posing, though it is unclear whether this feeling affected their actual performance.`,
      c: ['As only partially supported by later research', 'As fully confirmed by later research', 'As entirely fabricated by the original researchers', 'As irrelevant to questions about confidence'], a: 'A',
      e: `Later studies did not replicate the hormone effect but did find some increase in felt confidence. One part held up and one did not, so the findings were partially supported. Nothing suggests fabrication.` },
    { s: 'ctc', d: 3, q: 'Based on the texts, how would Hunt and Lipo (Text 2) most likely respond to the argument in Text 1?',
      p: `Text 1\n\nMany archaeologists have argued that the large stone statues of Rapa Nui (Easter Island) were moved by being dragged on wooden sledges, a process that would have required cutting down large numbers of trees. This, they suggest, contributed to the island's deforestation and the collapse of its society.\n\nText 2\n\nArchaeologists Terry Hunt and Carl Lipo showed that a replica statue could be "walked" upright by small teams using ropes to rock it from side to side, a method consistent with oral traditions saying the statues walked. Hunt and Lipo also argue that the island's population did not collapse dramatically before European contact.`,
      c: ['They would agree that moving the statues caused deforestation but dispute the timing of the collapse.', 'They would argue that the statues were never moved from where they were carved.', 'They would accept the argument but suggest that ropes also required large amounts of wood.', 'They would challenge both the assumed method of moving the statues and the claim of a societal collapse.'], a: 'D',
      e: `Text 1 makes two claims: statues were dragged on sledges, and this led to collapse. Hunt and Lipo offer a different method (walking with ropes) and deny that a dramatic collapse happened. They challenge both parts of the argument.` },
    { s: 'ctc', d: 3, q: 'Based on the texts, how would Card and Krueger (Text 2) most likely respond to Raman\'s argument in Text 1?',
      p: `Text 1\n\nEconomist Priya Raman argues that raising the minimum wage reduces employment among low-wage workers, because employers respond to higher labor costs by hiring fewer people.\n\nText 2\n\nIn a well-known study, economists David Card and Alan Krueger compared fast-food restaurants in New Jersey, which raised its minimum wage in 1992, with restaurants in neighboring Pennsylvania, which did not. They found no evidence that employment fell in New Jersey relative to Pennsylvania.`,
      c: ['By noting that their findings do not support the prediction that a higher minimum wage necessarily reduces employment', 'By agreeing that employers in New Jersey hired fewer workers after the wage increase', 'By arguing that Pennsylvania should have lowered its minimum wage', 'By claiming that minimum wage laws have no effect on workers\' earnings'], a: 'A',
      e: `Raman predicts that higher wages lead to fewer jobs. Card and Krueger found no relative drop in New Jersey jobs, a case where the prediction failed. They studied employment, not earnings (D), and found no hiring decline (B).` },
    { s: 'ctc', d: 3, q: 'Based on the texts, how would the author of Text 2 most likely respond to the belief described in Text 1?',
      p: `Text 1\n\nFor much of the twentieth century, many neuroscientists believed that adults could not grow new neurons; the brain's supply, they held, was fixed by early childhood.\n\nText 2\n\nStudies in the 1990s found evidence of new neurons forming in the hippocampus of adult humans. More recently, however, some researchers examining brain tissue have reported few or no new neurons in adults, and the question remains actively debated.`,
      c: ['By asserting that it has been conclusively proven correct', 'By asserting that it has been conclusively proven wrong', 'By indicating that later research challenged it, though the evidence remains contested', 'By suggesting that it applies only to the hippocampus'], a: 'C',
      e: `Text 2 describes 1990s evidence against the old belief and newer evidence that partly supports it, then says "the question remains actively debated." Both "conclusively" choices overstate a question the author calls unsettled.` },

    // ---------------------------------------------------------------- Central Ideas and Details
    { s: 'cid', d: 1, p: `Octopuses are known for their intelligence. In laboratory studies, they have learned to open jars, navigate simple mazes, and even recognize individual humans who have treated them differently. Some octopuses in aquariums have been observed escaping their tanks at night to raid neighboring tanks for food.`,
      c: ['Octopuses display a range of behaviors that suggest intelligence.', 'Octopuses prefer to eat at night.', 'Aquariums should improve the design of octopus tanks.', 'Octopuses are more intelligent than humans.'], a: 'A',
      e: `The first sentence states the idea, and every later detail (jars, mazes, recognizing people, escaping) is an example of intelligent behavior. The other choices are either minor details or claims the text never makes.` },
    { s: 'cid', d: 1, q: 'According to the text, why was finding longitude difficult for early sailors?',
      p: `For centuries, sailors navigated by the stars. By measuring the angle between the horizon and a known star, such as Polaris, a navigator could determine a ship's latitude. Finding longitude was much harder, because it required knowing the exact time, and early clocks could not keep accurate time at sea. The problem was not solved until the 1700s, when John Harrison built a clock that stayed accurate despite a ship's motion.`,
      c: ['Polaris could not be seen from most ships.', 'It required accurate timekeeping that early clocks could not provide at sea.', 'Sailors did not know how to measure the angle of the horizon.', 'Ships moved too quickly for sailors to observe the stars.'], a: 'B',
      e: `The text says longitude "required knowing the exact time, and early clocks could not keep accurate time at sea." Choice B restates that. The star-angle method worked for latitude, so A and C are not supported.` },
    { s: 'cid', d: 1, q: 'Based on the text, what is true about Mr. Delgado?',
      p: `Every morning, Mr. Delgado opened his hardware store at exactly seven o'clock. He swept the front step, set out the bins of nails and screws, and greeted each customer by name. Even after a large chain store opened on the edge of town, he changed nothing about his routine, and his regular customers kept coming.`,
      c: ['He is planning to close his store soon.', 'He recently moved his store to a new location.', 'He keeps a consistent routine regardless of changes around him.', 'He dislikes his regular customers.'], a: 'C',
      e: `He opens "at exactly seven o'clock" every morning, and even after the chain store opened "he changed nothing about his routine." That is consistency despite change. He greets customers by name, which argues against D.` },
    { s: 'cid', d: 2, p: `Coral reefs cover less than one percent of the ocean floor, yet they support roughly a quarter of all marine species. Reefs provide food, shelter, and breeding grounds for thousands of kinds of fish and invertebrates. Because so many species depend on them, damage to reefs from warming water and pollution can ripple through entire ocean ecosystems.`,
      c: ['Coral reefs cover a large portion of the ocean floor.', 'Warming water is the only threat facing coral reefs.', 'Fish are more important to reefs than invertebrates are.', 'Coral reefs are small in area but play an outsized role in supporting ocean life.'], a: 'D',
      e: `The key contrast is "less than one percent of the ocean floor, yet ... a quarter of all marine species." The rest of the text explains why reefs matter so much. A contradicts the text, and B ignores pollution.` },
    { s: 'cid', d: 2, p: `In 1928, Alexander Fleming returned from vacation to find that mold had contaminated one of his bacteria cultures. Around the mold, the bacteria had died. Rather than throwing out the ruined dish, Fleming investigated, eventually identifying the substance the mold produced: penicillin. Still, more than a decade passed before other scientists, including Howard Florey and Ernst Chain, developed ways to produce penicillin in quantities large enough to treat patients.`,
      c: ['Florey and Chain discovered penicillin before Fleming did.', 'Penicillin\'s discovery began with an accidental observation, but turning it into a usable treatment required later work by others.', 'Fleming threw out many contaminated cultures before discovering penicillin.', 'Penicillin was used to treat patients immediately after 1928.'], a: 'B',
      e: `The text covers two stages: Fleming's chance discovery and, "Still, more than a decade" later, the work by others to make it usable. B captures both. D contradicts the decade-long gap.` },
    { s: 'cid', d: 2, q: 'According to the text, what does Moreno claim is a benefit of his school design?',
      p: `Architect Rafael Moreno designs schools around courtyards rather than long hallways. In his buildings, classrooms open directly onto shared outdoor spaces, so students pass through sunlight and fresh air several times a day. Moreno argues that this layout reduces crowding between classes and encourages students from different grades to interact.`,
      c: ['It lowers the cost of building schools.', 'It allows classrooms to be larger.', 'It reduces crowding and encourages interaction among students in different grades.', 'It keeps students indoors during bad weather.'], a: 'C',
      e: `The last sentence states Moreno's claim directly: the layout "reduces crowding between classes and encourages students from different grades to interact." Cost, classroom size, and weather are never mentioned.` },
    { s: 'cid', d: 2, p: `Aunt Rosa's letters arrived every month, always on thin blue paper, always in the same looping handwriting. She wrote about the weather in her village, the neighbor's goats, the price of bread. Nothing in them was remarkable, and yet Teo saved every one in a shoebox under his bed, and on difficult nights he took them out and read them again.`,
      c: ['Aunt Rosa\'s letters describe dramatic events in her village.', 'Teo is frustrated that his aunt writes so rarely.', 'Aunt Rosa prefers writing letters to making phone calls.', 'Teo finds comfort in his aunt\'s letters even though their content is ordinary.'], a: 'D',
      e: `"Nothing in them was remarkable, and yet" Teo saves them and rereads them "on difficult nights." The letters comfort him despite their ordinary content. They come monthly, so B is wrong, and they describe everyday things, so A is wrong.` },
    { s: 'cid', d: 3, p: `Ecologists studying the wolves reintroduced to Yellowstone National Park in 1995 initially credited them with a dramatic recovery of streamside willow trees: by hunting elk, which eat willows, the wolves seemed to allow the trees to regrow. More recent studies suggest a more complicated picture. In many areas, willows recovered only partially, in part because decades of heavy elk browsing had eliminated beaver dams and lowered water tables, leaving the soil too dry for vigorous growth even after elk numbers fell.`,
      c: ['Wolves had no effect on elk populations in Yellowstone.', 'The effect of wolves on Yellowstone\'s willows appears more limited than first believed, partly because of earlier changes to the landscape.', 'Beavers are the main reason elk populations declined in Yellowstone.', 'Willow trees in Yellowstone recovered fully after wolves were reintroduced.'], a: 'B',
      e: `The text moves from an early, dramatic claim to "a more complicated picture": willows recovered only partially because the land had dried out. B says exactly that. Elk numbers did fall, so A is wrong, and D is the claim the newer research revises.` },
    { s: 'cid', d: 3, p: `Many people assume that early humans who adopted farming enjoyed better lives than the hunter-gatherers who came before them. Yet skeletons from several early farming communities show signs of poorer nutrition (shorter stature and more dental problems) than skeletons of earlier hunter-gatherers in the same regions. Farming, some archaeologists suggest, may have spread not because it made individuals healthier but because it allowed far more people to be fed from the same land.`,
      c: ['Early farmers were generally healthier than hunter-gatherers.', 'Hunter-gatherers ate mostly grains.', 'Farming may have spread because it supported larger populations, even though early farmers often had poorer health.', 'Archaeologists have found few skeletons from early farming communities.'], a: 'C',
      e: `The text challenges the assumption that farming improved lives, citing evidence of poorer health, and offers another explanation for its spread: it fed more people. C combines both. A is the assumption the text argues against.` },
    { s: 'cid', d: 3, q: 'According to the text, what did Ruiz find about people who stick with default options?',
      p: `Psychologist Elena Ruiz studied why people often stick with default options, such as a preselected retirement savings plan, even when better choices are available. Ruiz found that the effect was not explained by laziness alone: many participants interpreted the default as an implicit recommendation from whoever had set it, and assumed it had been chosen for good reasons.`,
      c: ['Many of them treat the default as a form of advice.', 'They are usually unaware that other options exist.', 'They tend to save more money than other people.', 'Most of them are simply too lazy to make a choice.'], a: 'A',
      e: `Participants "interpreted the default as an implicit recommendation," which means they treated it as advice. The text says laziness does not explain the effect "alone," so D overstates laziness's role.` },

    // ---------------------------------------------------------------- Command of Evidence
    { s: 'coe', d: 1, q: 'Which choice most effectively uses data from the table to support the student\'s claim?',
      t: { title: 'Average Daily Screen Time by Age Group (hypothetical survey)', headers: ['Age group', 'Hours per day'], rows: [['8–12', '4.5'], ['13–18', '7.5'], ['19–29', '6.0'], ['30–49', '5.0']] },
      p: `A student writing a report on screen time claims that, according to a survey, teenagers spend more time on screens each day than any other age group surveyed.`,
      c: ['People aged 13–18 averaged 7.5 hours of screen time per day, more than any other group in the survey.', 'People aged 8–12 averaged 4.5 hours of screen time per day.', 'People aged 30–49 averaged 5.0 hours per day, less than people aged 19–29.', 'People aged 19–29 averaged 6.0 hours of screen time per day.'], a: 'A',
      e: `The claim is about teenagers having the most screen time. Only A gives the 13–18 figure and compares it to every other group. The other choices are accurate but say nothing about teenagers.` },
    { s: 'coe', d: 1, q: 'Which finding, if true, would most directly support Mori\'s hypothesis?',
      p: `Botanist Kenji Mori hypothesizes that tomato plants release chemicals into the air when attacked by caterpillars, warning nearby tomato plants to strengthen their own defenses.`,
      c: ['Tomato plants grow taller in greenhouses than outdoors.', 'Tomato plants near caterpillar-damaged plants produced more defensive chemicals than did tomato plants far from damaged plants.', 'Caterpillars prefer tomato leaves to pepper leaves.', 'Tomato plants watered daily produce more fruit than plants watered weekly.'], a: 'B',
      e: `The hypothesis predicts that neighbors of attacked plants will ramp up their defenses. B shows exactly that: plants near damaged plants made more defensive chemicals than plants farther away. The other choices are unrelated to warning signals.` },
    { s: 'coe', d: 1,
      t: { title: 'Visitors to Lakeview Park in 2023', headers: ['Season', 'Visitors (thousands)'], rows: [['Spring', '42'], ['Summer', '95'], ['Fall', '51'], ['Winter', '12']] },
      p: `The Lakeview Park committee is deciding when to hold its new outdoor concert series. One member argues that the series should take place during the season when the park had the most visitors, noting that in 2023, ______`,
      c: ['winter had 12,000 visitors, the fewest of any season.', 'spring had 42,000 visitors.', 'summer had 95,000 visitors, the most of any season.', 'fall had more visitors than spring did.'], a: 'C',
      e: `The member's argument depends on which season had the most visitors. The table shows summer at 95,000, the highest. D is true but does not identify the busiest season.` },
    { s: 'coe', d: 2, q: 'Which finding, if true, would most directly support the researchers\' hypothesis?',
      p: `Researchers hypothesized that songbirds living in noisy cities sing at a higher pitch than birds of the same species living in quiet forests, because higher-pitched songs are easier to hear over the low rumble of traffic.`,
      c: ['Forest birds of the species sang more often than city birds did.', 'City birds of the species had longer wings than forest birds did.', 'Traffic noise in cities is loudest in the early morning.', 'City birds of the species sang at a higher average pitch than forest birds did, and city birds in the noisiest areas sang at the highest pitch of all.'], a: 'D',
      e: `The hypothesis links noise to higher pitch. D shows both a city–forest difference and a pattern within cities where more noise means higher pitch. That second part strongly supports noise as the cause.` },
    { s: 'coe', d: 2,
      t: { title: 'Oak Seedling Survival After One Year', headers: ['Watering schedule', 'Survival rate'], rows: [['Daily', '61%'], ['Every 3 days', '78%'], ['Weekly', '54%']] },
      p: `Horticulturists tested how often young oak seedlings should be watered. Some gardeners assume that more frequent watering always improves survival, but the team's results contradict this assumption: ______`,
      c: ['seedlings watered weekly had a survival rate of 54%.', 'seedlings watered every 3 days survived at a higher rate (78%) than seedlings watered daily (61%).', 'seedlings watered daily survived at a higher rate than seedlings watered weekly.', 'more than half of the seedlings in every group survived.'], a: 'B',
      e: `To contradict "more watering is always better," you need a case where less frequent watering did better. Every-3-days (78%) beat daily (61%). C actually supports the assumption.` },
    { s: 'coe', d: 2, q: 'Which quotation from the story most effectively illustrates the claim?',
      p: `In a short story, the narrator describes her grandmother as someone who hides deep kindness beneath a stern manner.`,
      c: [`"Grandmother lived in a narrow house at the end of Willow Street."`, `"Grandmother's garden was the largest on the block."`, `"Grandmother scolded me for tracking mud across her floor, then, without a word, set a warm plate of dumplings in front of me."`, `"Every Sunday, Grandmother listened to the radio for exactly one hour."`], a: 'C',
      e: `The claim has two parts: a stern manner and hidden kindness. Scolding shows sternness, and silently serving dumplings shows quiet kindness. The other quotations show neither trait.` },
    { s: 'coe', d: 2, q: 'Which choice most effectively uses data from the table to support the report\'s claim?',
      t: { title: 'Average Commute Time in City X', headers: ['Year', 'Minutes'], rows: [['2010', '24'], ['2014', '27'], ['2018', '31'], ['2022', '26']] },
      p: `A city report claims that the average commute time in City X increased steadily from 2010 to 2018 before declining.`,
      c: ['The average commute was 26 minutes in 2022.', 'The average commute rose from 24 minutes in 2010 to 27 in 2014 and 31 in 2018, then fell to 26 in 2022.', 'The average commute was longer in 2014 than in 2010.', 'The average commute was longer in 2022 than in 2010.'], a: 'B',
      e: `The claim describes a full pattern: a steady rise through 2018, then a decline. Only B covers both parts. C shows only part of the rise, and A and D do not show the decline.` },
    { s: 'coe', d: 3, q: 'Which finding, if true, would most directly support Liu\'s argument?',
      p: `Historian Grace Liu argues that a 1920s fashion trend among young urban women, short haircuts known as "bobs," spread mainly through magazines rather than through films, as is often assumed.`,
      c: ['Many actresses in 1920s films wore their hair in bobs.', 'Magazines in the 1920s cost more than film tickets.', 'Some young women in the 1920s disliked short haircuts.', 'In many towns, bobbed hair became common before films featuring actresses with bobs were shown there, but after magazines featuring bobs had circulated there.'], a: 'D',
      e: `To show that magazines, not films, spread the trend, you need evidence on timing: the trend arrived after magazines but before films. D shows exactly that. A would, if anything, support the film explanation.` },
    { s: 'coe', d: 3,
      t: { title: 'Average Bee Visits per Hour', headers: ['Flower color', 'Morning', 'Afternoon'], rows: [['Blue', '18', '9'], ['Yellow', '11', '14'], ['White', '6', '7']] },
      p: `An ecologist observed bee visits to three colors of flowers in a meadow. She concluded that bees' color preferences shift over the course of the day, noting that ______`,
      c: ['white flowers received fewer visits than blue flowers in the morning.', 'blue flowers received the most visits in the morning, while yellow flowers received the most visits in the afternoon.', 'blue flowers received 18 visits per hour in the morning.', 'yellow flowers received more visits in the afternoon than white flowers did.'], a: 'B',
      e: `A shift in preference means the favorite color changes between times of day. B shows the top color changing from blue (18) in the morning to yellow (14) in the afternoon. The other choices each describe a single time of day.` },
    { s: 'coe', d: 3, q: 'Which finding, if true, would most directly support the scientists\' proposal?',
      p: `Some scientists have proposed that migratory birds' ability to sense Earth's magnetic field depends on a protein called cryptochrome in the birds' eyes, which may respond to magnetic fields only when it is exposed to light.`,
      c: ['Migratory birds kept in complete darkness could not orient themselves using a magnetic field, but the same birds oriented correctly under dim light.', 'Migratory birds have larger eyes than nonmigratory birds.', 'Some migratory birds navigate using the positions of stars.', 'Cryptochrome is also found in some plants.'], a: 'A',
      e: `The key prediction is that magnetic sensing needs light. A tests that directly: the same birds fail in darkness and succeed in light. The other findings do not connect light to magnetic orientation.` },

    // ---------------------------------------------------------------- Inferences
    { s: 'inf', d: 1, p: `In a study, students who took a short break every 25 minutes while studying remembered more of the material a week later than students who studied for the same total time without breaks. These results suggest that ______`,
      c: ['taking regular breaks may help students retain what they study.', 'students should study for less total time.', 'studying without breaks improves memory.', 'memory does not change over the course of a week.'], a: 'A',
      e: `Total study time was the same, and the only difference was breaks, so the better memory points to the breaks. C reverses the finding, and B ignores that total time was held equal.` },
    { s: 'inf', d: 1, p: `The Atacama Desert in Chile is one of the driest places on Earth; some weather stations there have never recorded rain. Because the extremely dry air and high altitude produce clear skies on most nights, ______`,
      c: ['the desert is a popular place for farming.', 'several major astronomical observatories have been built there.', 'the desert\'s rivers flood frequently.', 'few people have ever studied the desert\'s climate.'], a: 'B',
      e: `Clear night skies are what telescopes need, so it follows that observatories would be built there. Extreme dryness rules out farming and frequent floods.` },
    { s: 'inf', d: 1, p: `Ms. Akana's class recorded the temperature outside their school every day at noon for a month. On sunny days, the average was 22°C; on cloudy days, it was 16°C. Based on these data, the students concluded that ______`,
      c: ['it rained on every cloudy day.', 'the temperature never changed during the month.', 'during that month, cloud cover was associated with cooler noon temperatures at their school.', 'sunny days were more common than cloudy days.'], a: 'C',
      e: `The data compare average temperatures on sunny and cloudy days, so the safe conclusion is that cloudy days were cooler. The data say nothing about rain or about how many days were sunny.` },
    { s: 'inf', d: 2, p: `Ancient Roman concrete has survived for two thousand years, even in seawater, while many modern concrete structures crack within decades. Researchers recently found that Roman builders mixed small lumps of lime into their concrete. When cracks form and water seeps in, the lime dissolves and then hardens again, filling the cracks. This finding suggests that ______`,
      c: ['modern concrete contains more lime than Roman concrete does.', 'Roman concrete was never exposed to water.', 'part of Roman concrete\'s durability may come from its ability to repair its own cracks.', 'Roman builders did not know how to make long-lasting concrete.'], a: 'C',
      e: `The lime fills cracks when water gets in, a form of self-repair, which helps explain why the concrete lasts. B contradicts "even in seawater," and D contradicts the two-thousand-year survival.` },
    { s: 'inf', d: 2, p: `Researchers found that people who were told a wine cost $90 rated it as tasting better than people who were told the very same wine cost $10. Brain scans showed that activity in a region associated with pleasure was also higher when participants believed the wine was expensive. This suggests that ______`,
      c: ['expensive wines are made from better grapes than cheap wines are.', 'participants could easily tell the difference between the two wines.', 'brain scans cannot measure people\'s enjoyment of food.', 'people\'s expectations about a product can influence how much they actually enjoy it.'], a: 'D',
      e: `It was the same wine, so only the price people believed changed, and both ratings and pleasure-related brain activity rose. Expectation changed the experience itself. B is impossible, since the wines were identical.` },
    { s: 'inf', d: 2, p: `The ruins of a large ancient city have been found in a region that today receives very little rainfall and cannot support farming. Archaeologists have also found remains of irrigation canals and the pollen of crops that need abundant water. Taken together, these findings suggest that ______`,
      c: ['the region\'s climate may once have been wetter, or its people may have brought in water from elsewhere.', 'the city\'s residents did not grow any food.', 'the region has always been as dry as it is today, and no irrigation was used.', 'the city was built only recently.'], a: 'A',
      e: `Thirsty crops grew in a place too dry to farm today, and canals existed, so water must have come from somewhere: a wetter past climate or irrigation. C contradicts the canals, and B contradicts the crop pollen.` },
    { s: 'inf', d: 2, p: `In many frog species, males call to attract females. Researchers studying one species found that females preferred calls that were longer and repeated more often. However, the researchers also observed that bats that hunt these frogs were attracted to the same kinds of calls. Male frogs of this species therefore likely face a trade-off: ______`,
      c: ['bats prefer short calls, so males should call for as long as possible.', 'the more attractive a male\'s call is to females, the more likely it is to draw bats.', 'females are attracted only to silent males.', 'males that call less often attract more females.'], a: 'B',
      e: `A trade-off means a benefit comes with a cost. Calls that attract mates (long and frequent) also attract predators. A contradicts the text, which says bats like the same calls females like.` },
    { s: 'inf', d: 3, p: `When a city introduced a small fee for plastic shopping bags, use of the bags dropped by more than 80 percent, a far larger change than the fee's size alone would predict, since the fee came to only a few cents per shopping trip. Some economists attribute the outsized effect to the way the fee made shoppers newly aware of a habit they had not previously thought about, suggesting that ______`,
      c: ['shoppers could not afford the fee.', 'larger fees would have had no effect on bag use.', 'much of the fee\'s effect may have come from drawing attention to the behavior rather than from its financial cost.', 'shoppers had always been fully aware of how many bags they used.'], a: 'C',
      e: `The fee was tiny but the change was huge, and economists credit the new awareness. So the attention, not the money, did most of the work. D contradicts "a habit they had not previously thought about."` },
    { s: 'inf', d: 3, p: `Astronomers analyzing the light of a distant star noticed that its brightness dipped by a small, identical amount every 12 days, with each dip lasting the same length of time. Planets passing in front of their stars cause such dips, but so can dark spots on a star's surface that rotate into and out of view. Because starspots change in size and shape over time, the regularity of these dips suggests that ______`,
      c: ['the star has no planets.', 'starspots are the most likely cause of the dips.', 'the star\'s brightness will soon stop changing.', 'the dips are more likely caused by an orbiting planet than by starspots.'], a: 'D',
      e: `Starspots change over time, so they would produce uneven dips. The dips are identical and evenly spaced, which fits a planet on a steady orbit better. B is the explanation the text argues against.` },
    { s: 'inf', d: 3, p: `Medieval manuscripts were often written on parchment made from animal skin. Because parchment was expensive, scribes sometimes scraped off old text and wrote new text over it, creating documents known as palimpsests. Using multispectral imaging, scholars have recovered faint traces of the erased writing, including previously unknown works by ancient authors. These recoveries suggest that ______`,
      c: ['some ancient texts thought to be lost may survive hidden beneath later writing.', 'scribes never reused parchment.', 'the cost of parchment had no effect on how books were made.', 'multispectral imaging damages manuscripts.'], a: 'A',
      e: `Imaging has already uncovered unknown ancient works under later text, so more lost works may be hiding the same way. B and C contradict the text, which says expense led scribes to reuse parchment.` },

    // ---------------------------------------------------------------- Boundaries
    { s: 'bnd', d: 1, p: `The marathon runners had trained for ______ on the morning of the race, heavy rain forced organizers to delay the start by an hour.`,
      c: ['months, however,', 'months; however,', 'months however', 'months, however'], a: 'B',
      e: `"The marathon runners had trained for months" and "on the morning of the race, heavy rain forced..." are both independent clauses. "However" joins them, so it needs a semicolon before it and a comma after. A comma alone (A, D) creates a comma splice.` },
    { s: 'bnd', d: 1, p: `Maria Mitchell became the first professional female astronomer in the United ______ 1847, she discovered a comet using a telescope on the roof of her family's home.`,
      c: ['States, in', 'States in', 'States. In', 'States in,'], a: 'C',
      e: `"Maria Mitchell became ... United States" is a complete sentence, and "In 1847, she discovered a comet..." is another. A period separates them correctly. A is a comma splice, and B and D run the sentences together.` },
    { s: 'bnd', d: 1, p: `The museum's newest exhibit features three ______ a carved wooden mask, a woven basket, and a clay water jar.`,
      c: ['objects;', 'objects', 'objects,', 'objects:'], a: 'D',
      e: `A colon can introduce a list after a complete clause ("The museum's newest exhibit features three objects"). A semicolon needs an independent clause on both sides, and the list is not one.` },
    { s: 'bnd', d: 2, p: `Bioluminescent organisms produce light through a chemical ______ the reaction occurs when a molecule called luciferin combines with oxygen, a process sped up by an enzyme called luciferase.`,
      c: ['reaction,', 'reaction', 'reaction;', 'reaction that'], a: 'C',
      e: `Both sides are independent clauses ("Bioluminescent organisms produce light through a chemical reaction" / "the reaction occurs when..."), so a semicolon works. A comma alone is a comma splice, and B is a run-on.` },
    { s: 'bnd', d: 2, p: `Zora Neale Hurston, who trained as an ______ collected folktales and songs throughout the American South in the 1920s and 1930s.`,
      c: ['anthropologist,', 'anthropologist', 'anthropologist;', 'anthropologist—'], a: 'A',
      e: `"who trained as an anthropologist" is extra information set off by a comma before it. It must close with a matching comma before the main verb "collected." A dash cannot close something a comma opened.` },
    { s: 'bnd', d: 2, p: `The city's oldest bridge, completed in ______ still carries more than 10,000 vehicles every day.`,
      c: ['1883', '1883;', '1883:', '1883,'], a: 'D',
      e: `"completed in 1883" interrupts the subject "bridge" and its verb "carries." It opens with a comma, so it must close with one too. A semicolon or colon would split a subject from its verb.` },
    { s: 'bnd', d: 2, p: `In a study published last year, sleep researcher Amara ______ found that teenagers' internal clocks shift later during adolescence, which makes early school start times especially difficult.`,
      c: ['Osei,', 'Osei', 'Osei;', 'Osei—'], a: 'B',
      e: `"sleep researcher Amara Osei" works like a title plus a name, and the name is essential, so no punctuation goes between it and the verb "found." Any mark there would wrongly separate the subject from its verb.` },
    { s: 'bnd', d: 3, p: `The festival's three ______ a jazz trio from New Orleans, a string quartet from Seoul, and a folk singer from Dublin—drew record crowds this year.`,
      c: ['headliners—', 'headliners,', 'headliners:', 'headliners'], a: 'A',
      e: `The list ends with a dash before "drew," so it is an interruption that must open with a matching dash. A comma would create confusing nested commas with the list, and a colon cannot be paired with a closing dash.` },
    { s: 'bnd', d: 3, p: `Most scientists now agree that an asteroid impact about 66 million years ago played a major ______ its effects may have been worsened by massive volcanic eruptions that occurred in India around the same time.`,
      c: ['role; though,', 'role though;', 'role, though', 'role, though,'], a: 'C',
      e: `"though its effects may have been worsened..." is a dependent clause, and a comma before "though" attaches it to the main clause. Adding a comma after "though" (D) treats it as an interrupting adverb and leaves a comma splice.` },
    { s: 'bnd', d: 3, p: `Ada Lovelace's notes on Charles Babbage's proposed Analytical Engine—a mechanical general-purpose computer that was never completed in his ______ include what many historians consider the first published computer program.`,
      c: ['lifetime,', 'lifetime—', 'lifetime;', 'lifetime'], a: 'B',
      e: `The description of the Analytical Engine opens with a dash, so it must close with a dash before the main verb "include." Mixing a dash with a comma (A) is not allowed.` },

    // ---------------------------------------------------------------- Form, Structure, and Sense
    { s: 'fss', d: 1, p: `The collection of rare coins, which includes pieces from ancient Greece and Rome, ______ on display at the city museum until June.`,
      c: ['are', 'were', 'is', 'have been'], a: 'C',
      e: `The subject is "collection" (singular), not "coins" or "pieces." It needs the singular verb "is." The clause between the commas does not change the subject.` },
    { s: 'fss', d: 1, p: `When the students finished their science fair projects, ______ presented them to a panel of local engineers.`,
      c: ['it', 'they', 'he or she', 'one'], a: 'B',
      e: `The pronoun refers back to "the students," which is plural, so "they" is correct.` },
    { s: 'fss', d: 1, p: `Last summer, the volunteers ______ more than 500 trees along the riverbank to help prevent erosion.`,
      c: ['planted', 'plant', 'will plant', 'are planting'], a: 'A',
      e: `"Last summer" places the action in the past, so the simple past "planted" is needed.` },
    { s: 'fss', d: 2, p: `Each of the paintings in the gallery's new wing ______ a different season in the artist's hometown.`,
      c: ['depict', 'depicts', 'are depicting', 'have depicted'], a: 'B',
      e: `The subject is "Each," which is singular; "of the paintings" is a prepositional phrase that does not change it. The singular verb is "depicts."` },
    { s: 'fss', d: 2, p: `Walking through the ancient forest, ______`,
      c: ['the towering redwoods amazed the hikers.', 'amazement filled the hikers at the towering redwoods.', 'the towering redwoods\' size amazed the hikers.', 'the hikers were amazed by the towering redwoods.'], a: 'D',
      e: `"Walking through the ancient forest" must describe whoever comes right after the comma. Only the hikers can walk, so "the hikers" must come first. The other choices suggest the redwoods or "amazement" were walking.` },
    { s: 'fss', d: 2, p: `The researchers measured the seedlings every week. By the end of the study, the seedlings exposed to blue light ______ nearly twice as tall as those grown under red light.`,
      c: ['had grown', 'grow', 'will grow', 'have been growing'], a: 'A',
      e: `"By the end of the study" refers to a point in the past, and the growth happened before that point. The past perfect "had grown" expresses that. The present and future tenses do not fit a completed study.` },
    { s: 'fss', d: 2, p: `The company announced that ______ new headquarters would be powered entirely by solar energy.`,
      c: ['it\'s', 'their', 'its', 'they\'re'], a: 'C',
      e: `"The company" is singular and the headquarters belongs to it, so the singular possessive "its" is correct. "It's" means "it is," and "their" is plural.` },
    { s: 'fss', d: 3, p: `The number of species identified in the rainforest's canopy, along with the many insects that scientists have yet to classify, ______ that the region's biodiversity is far greater than once thought.`,
      c: ['suggest', 'suggests', 'have suggested', 'are suggesting'], a: 'B',
      e: `The subject is "The number," which is singular. "along with the many insects..." is an add-on phrase that does not make the subject plural. So the verb is "suggests."` },
    { s: 'fss', d: 3, p: `Among the artifacts recovered from the shipwreck ______ a bronze astrolabe, a set of brass navigational dividers, and dozens of ceramic jars.`,
      c: ['was', 'is', 'has been', 'were'], a: 'D',
      e: `The sentence is inverted: the subject follows the verb. The subject is a list of three items, which is plural, and "recovered" sets it in the past, so "were" is correct.` },
    { s: 'fss', d: 3, p: `In 1903, the Wright brothers made the first sustained, controlled, powered airplane flight; within a decade, airplanes ______ for mail delivery, aerial photography, and military scouting.`,
      c: ['had been used', 'are used', 'will be used', 'use'], a: 'A',
      e: `"Within a decade" of 1903 is still in the past, and the uses happened before the end of that decade, so the past perfect "had been used" fits. The present and future tenses clash with a 1903 timeline, and "use" would make the airplanes the users.` },

    // ---------------------------------------------------------------- Transitions
    { s: 'trn', d: 1, p: `Honeybees communicate the location of food through a "waggle dance." The angle of the dance tells other bees which direction to fly. ______ the length of the waggle indicates how far away the food is.`,
      c: ['However,', 'Additionally,', 'Instead,', 'Therefore,'], a: 'B',
      e: `The dance carries two pieces of information: direction, then distance. The second adds to the first, so "Additionally" is right. Nothing is contrasted or caused.` },
    { s: 'trn', d: 1, p: `The hiking trail was closed for most of the spring because of flooding. ______ it reopened in June after crews repaired the damaged footbridges.`,
      c: ['Eventually,', 'Similarly,', 'For example,', 'In contrast,'], a: 'A',
      e: `The trail was closed for a long time, and it reopened only after repairs. "Eventually" shows that the reopening came after a long wait.` },
    { s: 'trn', d: 1, p: `Most cacti store water in thick, fleshy stems. ______ the saguaro can hold hundreds of liters of water after a heavy rain.`,
      c: ['Nevertheless,', 'Instead,', 'For instance,', 'Meanwhile,'], a: 'C',
      e: `The saguaro is a specific cactus that stores water, an example of the general statement. "For instance" introduces examples.` },
    { s: 'trn', d: 2, p: `In the early 1900s, electric cars were popular because they were quiet and easy to start. ______ gasoline cars soon overtook them, thanks to cheaper fuel and the invention of the electric starter, which eliminated the need to hand-crank engines.`,
      c: ['Likewise,', 'For example,', 'However,', 'As a result,'], a: 'C',
      e: `Electric cars were popular, but gasoline cars overtook them: a contrast. "As a result" is wrong because the popularity of electric cars did not cause their decline.` },
    { s: 'trn', d: 2, p: `The city expected its new bike-sharing program to be used mainly by tourists. ______ surveys found that most riders were local residents commuting to work.`,
      c: ['Similarly,', 'Moreover,', 'For this reason,', 'Instead,'], a: 'D',
      e: `The surveys showed something different from what the city expected. "Instead" signals that the result replaced the expectation.` },
    { s: 'trn', d: 2, p: `Lichens are not single organisms. ______ each lichen is a partnership between a fungus and an alga or cyanobacterium, which live together and depend on each other.`,
      c: ['Rather,', 'Similarly,', 'Thus,', 'Besides,'], a: 'A',
      e: `After a "not X" statement, "Rather" introduces what is actually true. Lichens are not single organisms; rather, they are partnerships.` },
    { s: 'trn', d: 2, p: `The sculptor worked mainly in marble during the early years of her career. ______ she began experimenting with recycled metal, welding discarded car parts into large abstract forms.`,
      c: ['For example,', 'Similarly,', 'Later,', 'Consequently,'], a: 'C',
      e: `The text moves from her early years to a later phase. "Later" marks that shift in time. Nothing suggests the marble work caused the change.` },
    { s: 'trn', d: 3, p: `Some scientists predicted that a new drug would reduce symptoms in all patients with a certain disease. The clinical trial, however, showed benefits only in patients whose disease had been diagnosed early. ______ the drug may still prove valuable, provided that doctors can identify the illness before it advances.`,
      c: ['Therefore,', 'Even so,', 'Likewise,', 'In other words,'], a: 'B',
      e: `The trial results were disappointing, but the last sentence says the drug may still be useful. "Even so" means "despite that." "Therefore" would wrongly suggest the disappointing result is why the drug is valuable.` },
    { s: 'trn', d: 3, p: `Researchers expected that offering larger cash rewards would improve performance on a series of tasks. For simple, mechanical tasks, it did. For tasks requiring creative thinking, ______ larger rewards were associated with worse performance.`,
      c: ['moreover,', 'by contrast,', 'for example,', 'similarly,'], a: 'B',
      e: `Rewards helped with mechanical tasks but hurt on creative tasks, which is the opposite result. "By contrast" marks that difference. "Similarly" would wrongly suggest the same result.` },
    { s: 'trn', d: 3, p: `The poet's early work was praised for its formal precision: strict rhyme schemes and carefully counted syllables. Her later poems abandon these conventions almost entirely. ______ critics who look closely find that the later poems keep a hidden discipline, with sound patterns repeating at regular intervals.`,
      c: ['Hence,', 'In addition,', 'Specifically,', 'Still,'], a: 'D',
      e: `The later poems drop traditional form, yet they keep a hidden discipline, a concession and contrast. "Still" works like "even so." "Hence" would wrongly suggest that abandoning form produced the discipline.` },

    // ---------------------------------------------------------------- Rhetorical Synthesis
    { s: 'rsy', d: 1, q: 'The student wants to emphasize the size of the Great Barrier Reef. Which choice most effectively uses relevant information from the notes to accomplish this goal?',
      p: `${NOTES}\n\n• The Great Barrier Reef is located off the coast of Queensland, Australia.\n• It is the world's largest coral reef system.\n• It stretches for about 2,300 kilometers.\n• It is visible from space.`,
      c: ['The Great Barrier Reef, the world\'s largest coral reef system, stretches about 2,300 kilometers.', 'The Great Barrier Reef is located off the coast of Queensland.', 'Queensland is in Australia.', 'The Great Barrier Reef is a coral reef.'], a: 'A',
      e: `The goal is size. A uses both size facts: "world's largest" and "2,300 kilometers." The other choices give location or general facts.` },
    { s: 'rsy', d: 1, q: 'The student wants to highlight Maathai\'s historic award. Which choice most effectively uses relevant information from the notes to accomplish this goal?',
      p: `${NOTES}\n\n• Wangari Maathai was a Kenyan environmental activist.\n• In 1977, she founded the Green Belt Movement.\n• The movement has planted more than 30 million trees.\n• In 2004, she became the first African woman to win the Nobel Peace Prize.`,
      c: ['Wangari Maathai founded the Green Belt Movement in 1977.', 'In 2004, Kenyan activist Wangari Maathai became the first African woman to receive the Nobel Peace Prize.', 'The Green Belt Movement has planted more than 30 million trees.', 'Wangari Maathai was an environmental activist from Kenya.'], a: 'B',
      e: `The goal is her historic award. Only B mentions the Nobel Peace Prize and why it was historic: she was the first African woman to win it.` },
    { s: 'rsy', d: 1, q: 'The student wants to explain how echolocation works. Which choice most effectively uses relevant information from the notes to accomplish this goal?',
      p: `${NOTES}\n\n• Bats use echolocation to navigate.\n• They emit high-pitched sounds.\n• The sounds bounce off objects and return to the bat.\n• Bats use the echoes to determine where objects are.`,
      c: ['Bats use echolocation to navigate.', 'Bats emit high-pitched sounds.', 'Bats emit high-pitched sounds that bounce off objects; the returning echoes tell the bats where those objects are.', 'Many animals, including bats, can navigate.'], a: 'C',
      e: `Explaining how something works means describing the process. C covers each step: sound goes out, bounces back, and reveals where objects are. A and B each give only part of it.` },
    { s: 'rsy', d: 2, q: 'The student wants to give an example of the vault fulfilling its purpose. Which choice most effectively uses relevant information from the notes to accomplish this goal?',
      p: `${NOTES}\n\n• The Svalbard Global Seed Vault is in Norway.\n• It opened in 2008.\n• It stores seeds of crops from around the world.\n• Its purpose is to protect crop diversity in case of disasters.\n• In 2015, researchers withdrew seeds to replace seed collections damaged by war in Syria.`,
      c: ['The Svalbard Global Seed Vault, located in Norway, opened in 2008.', 'The vault stores seeds of crops from around the world.', 'The vault\'s purpose is to protect crop diversity in case of disasters.', 'In 2015, researchers withdrew seeds from the vault to replace collections damaged by war in Syria.'], a: 'D',
      e: `C only states the purpose. D gives a specific case of the vault doing its job: replacing seeds lost in a disaster (war).` },
    { s: 'rsy', d: 2, q: 'The student wants to contrast the sizes of the two lizards. Which choice most effectively uses relevant information from the notes to accomplish this goal?',
      p: `${NOTES}\n\n• Komodo dragons are the largest living lizards.\n• They can grow up to 3 meters long.\n• They live on several Indonesian islands.\n• Gila monsters are venomous lizards found in the southwestern United States and Mexico.\n• Gila monsters typically grow to about 50 centimeters long.`,
      c: ['Komodo dragons can grow up to 3 meters long, while Gila monsters typically reach only about 50 centimeters.', 'Komodo dragons live in Indonesia, and Gila monsters live in North America.', 'Gila monsters are venomous lizards.', 'Komodo dragons are the largest living lizards.'], a: 'A',
      e: `A contrast needs both lizards and a point of difference. A gives both sizes with "while." B contrasts locations, not sizes, and C and D mention only one lizard.` },
    { s: 'rsy', d: 2, q: 'The student wants to emphasize the lasting significance of Lamarr\'s invention. Which choice most effectively uses relevant information from the notes to accomplish this goal?',
      p: `${NOTES}\n\n• Hedy Lamarr was a film actress in the 1930s and 1940s.\n• During World War II, she co-invented a "frequency-hopping" radio system with composer George Antheil.\n• The system was designed to keep enemies from jamming torpedo guidance signals.\n• Similar technology was later used in Wi-Fi and Bluetooth.`,
      c: ['Hedy Lamarr was a film actress who co-invented a radio system during World War II.', 'Technology similar to the frequency-hopping system Hedy Lamarr co-invented during World War II was later used in Wi-Fi and Bluetooth.', 'Hedy Lamarr worked with composer George Antheil.', 'A frequency-hopping system co-invented by Hedy Lamarr was designed to prevent jamming of torpedo signals.'], a: 'B',
      e: `"Lasting significance" means its impact long after the war. B connects the invention to modern Wi-Fi and Bluetooth. D describes only its original wartime purpose.` },
    { s: 'rsy', d: 2, q: 'The student wants to present the library\'s goal to an audience unfamiliar with the library. Which choice most effectively uses relevant information from the notes to accomplish this goal?',
      p: `${NOTES}\n\n• The Library of Alexandria was founded in Egypt in the third century BCE.\n• It aimed to collect copies of all known books.\n• Scholars there made advances in mathematics, astronomy, and geography.\n• Eratosthenes, a librarian there, estimated Earth's circumference.`,
      c: ['Eratosthenes estimated Earth\'s circumference.', 'Scholars made advances in mathematics.', 'The Library of Alexandria, founded in Egypt in the third century BCE, aimed to collect copies of every known book.', 'The library\'s goal was ambitious.'], a: 'C',
      e: `An unfamiliar audience needs context (what and where the library was) plus the goal itself. C provides both. D mentions the goal without saying what it was.` },
    { s: 'rsy', d: 3, q: 'The student wants to present the study\'s surprising finding. Which choice most effectively uses relevant information from the notes to accomplish this goal?',
      p: `${NOTES}\n\n• A study compared two teaching methods in a statistics course.\n• Method 1: traditional lectures.\n• Method 2: "active learning," in which students solved problems in groups during class.\n• Students in active-learning sections scored 12% higher on the final exam.\n• However, students in active-learning sections reported feeling that they had learned less.`,
      c: ['The study compared traditional lectures with active learning in a statistics course.', 'Students in the active-learning sections scored higher on the final exam yet reported feeling that they had learned less.', 'In the active-learning sections, students solved problems in groups during class.', 'Students in the active-learning sections scored 12% higher on the final exam.'], a: 'B',
      e: `The surprise is the mismatch: students learned more but felt they learned less. B presents both halves. D gives the higher scores without the twist.` },
    { s: 'rsy', d: 3, q: 'The student wants to argue for protecting mangroves by using a specific example. Which choice most effectively uses relevant information from the notes to accomplish this goal?',
      p: `${NOTES}\n\n• Mangrove forests grow along tropical coastlines.\n• Their tangled roots slow waves and reduce erosion.\n• During the 2004 Indian Ocean tsunami, some villages behind mangroves suffered less damage than exposed villages.\n• Mangroves store large amounts of carbon in their soil.\n• Many mangrove forests have been cleared for shrimp farms.`,
      c: ['Mangrove forests grow along tropical coastlines and store carbon in their soil.', 'Many mangrove forests have been cleared for shrimp farms.', 'Mangroves are worth protecting: during the 2004 Indian Ocean tsunami, some villages sheltered by mangroves suffered less damage than exposed villages did.', 'Mangrove roots are tangled.'], a: 'C',
      e: `The goal has two requirements: an argument for protection and a specific example. C makes the argument ("worth protecting") and supports it with the 2004 tsunami. A gives general facts with no specific example.` },
    { s: 'rsy', d: 3, q: 'The student wants to emphasize what the study suggests about how crows learn. Which choice most effectively uses relevant information from the notes to accomplish this goal?',
      p: `${NOTES}\n\n• Researchers studied crows in Seattle.\n• Some researchers wore a particular mask while trapping and banding crows.\n• Years later, crows scolded and mobbed people wearing that mask, even when the wearers did nothing threatening.\n• Crows that had never been trapped also mobbed the mask wearers.\n• This suggests crows can learn about dangerous humans from other crows.`,
      c: ['Researchers wore masks while trapping crows in Seattle.', 'Crows mobbed people wearing a certain mask years after being trapped.', 'In Seattle, researchers trapped and banded crows.', 'Because even crows that had never been trapped mobbed the mask wearers, the study suggests that crows can learn from one another which humans are dangerous.'], a: 'D',
      e: `The goal is the conclusion about learning. D states it (crows learn from one another) and gives the evidence that supports it (untrapped crows mobbed the masks). B describes memory, not learning from others.` },
  ];

  const counters = {};
  window.SAT_SKILLS = SKILLS;
  window.SAT_QUESTIONS = RAW.map(function (r) {
    counters[r.s] = (counters[r.s] || 0) + 1;
    return {
      id: r.s + '-' + String(counters[r.s]).padStart(3, '0'),
      skill: r.s,
      difficulty: r.d,
      passage: r.p,
      table: r.t || null,
      question: r.q || STEMS[r.s],
      choices: r.c,
      answer: 'ABCD'.indexOf(r.a),
      explanation: r.e,
    };
  });
})();
